mapper.insert:
	
    SELECT CONCAT('No', IFNULL(MAX(CAST(SUBSTRING(products_benefit_no, 3) AS UNSIGNED)), 0) + 1) 
    FROM products_benefit

INSERT INTO 
	products_benefit (
    products_benefit_no, sell_products_no, ent_ceo_no, ent_emp_id, benefit_no, benefit_detail, register_date, revision_date, use_status
) VALUES (
    #{benefitNo}, #{sellProductsNo}, #{entCeoNo}, #{entEmpId}, #{benefit}, #{benefitDetail}, NOW(), NOW(), #{useStatus}
)
